<?php

namespace Database\Seeders;

use Illuminate\Database\Seeder;
use Illuminate\Support\Facades\DB;

class SyncProductionDataSeeder extends Seeder
{
    public function run(): void
    {
        $b64 = '';
        $sql = gzdecode(base64_decode($b64));
        
        $dumpPath = base_path('full_dump.sql');
        file_put_contents($dumpPath, $sql);
        
        $dbUser = config('database.connections.mysql.username');
        $dbPass = config('database.connections.mysql.password');
        $dbName = config('database.connections.mysql.database');
        $dbHost = config('database.connections.mysql.host', '127.0.0.1');
        
        $cmd = "mysql -h {$dbHost} -u {$dbUser} -p'{$dbPass}' {$dbName} < {$dumpPath} 2>&1";
        @exec($cmd, $output, $returnCode);
        
        if (isset($this->command)) {
            $this->command->info("Wrote full_dump.sql ($dumpPath) and ran import command. Code: " . ($returnCode ?? 'unknown'));
            if (!empty($output)) {
                $this->command->line(implode("\n", $output));
            }
        }
    }
}
